<?php
namespace App\Policies;
use App\Models\{Opportunity,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class OpportunityPolicy { use HandlesAuthorization,CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_opportunity');} public function view(User $u,Opportunity $r):bool{return $this->canForRecord($u,'view_opportunity',$r);} public function create(User $u):bool{return $u->can('create_opportunity');} public function update(User $u,Opportunity $r):bool{return $this->canForRecord($u,'update_opportunity',$r);} public function delete(User $u,Opportunity $r):bool{return $this->canForRecord($u,'delete_opportunity',$r)&&!$r->closed_at;} public function deleteAny(User $u):bool{return $u->can('delete_any_opportunity');} public function restore(User $u,Opportunity $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function forceDelete(User $u,Opportunity $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function replicate(User $u,Opportunity $r):bool{return false;} public function reorder(User $u):bool{return false;} public function assign(User $u,Opportunity $r):bool{return $this->canForRecord($u,'assign_opportunity',$r);} public function moveStage(User $u,Opportunity $r):bool{return $this->canForRecord($u,'move_opportunity_stage',$r);} }